"""Report figures and tables (F6.1, FR-24): everything the report shows, generated by code.

    docker compose exec spark python -m musin.report --config config/pipeline.yaml

Reads:  reports/tables/*.csv (main graph `full`, P3–P5) and
        reports/tables/variants/<name>/*.csv for every graph under `variants`
Writes: reports/tables/{sensitivity_top_lists,sensitivity_agreement,
                        graph_instances,pipeline_funnel}.csv
        reports/figures/{benchmark_pagerank,centrality_agreement,communities_sizes,
                         communities_composition,validation_ranks,trends_edge_types,
                         graph_build_instances}.png
        reports/tables/report/<name>.{md,tex}   report-ready tables (rewritten as a whole)
        reports/README.md                       manifest of every figure and table

No Spark and no Neo4j: every input is an aggregated table the P3–P5 stages
already wrote, so the stage runs in seconds and can run next to anything.
Before writing, it checks that the main tables describe one build of `full`
and each variant folder one build of `full-<name>` (musin.report.inputs), so
a report can't mix results of two graph builds.
"""

from __future__ import annotations

import argparse
import logging
import shutil
import sys
import time

import pandas as pd

from musin.analytics.common import write_table
from musin.common.config import Config, load_config
from musin.common.layers import figures_dir, results_dir
from musin.report import derived, figures, tables
from musin.report.formats import ReportTable, write_table_files
from musin.report.inputs import MAIN_GRAPH, Tables, check_one_build
from musin.report.manifest import render

log = logging.getLogger("musin.report")


def _check_depth(frame: pd.DataFrame, rank_col: str, k: int, what: str) -> None:
    """A top list must reach rank k, or a top-k comparison would silently use fewer."""
    if frame[rank_col].max() < k:
        raise ValueError(f"{what} reaches rank {frame[rank_col].max()}, config asks for {k}")


def sensitivity(cfg: Config, main: Tables) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Main graph against every variant in config `variants` (F4.7, D-035)."""
    k_c, k_b = int(cfg.get("analysis.top_k_centrality")), int(cfg.get("analysis.top_k_bridges"))
    _check_depth(main("centrality_top.csv"), "rank", k_c, "centrality_top.csv")
    _check_depth(main("bridges_top.csv"), "bridge_rank", k_b, "bridges_top.csv")
    lists, agree = [], []
    for name in sorted(cfg.get("variants")):
        var = Tables(results_dir(cfg, f"{MAIN_GRAPH}-{name}"))
        fp = check_one_build(var, f"{MAIN_GRAPH}-{name}")
        log.info("variant %s: %s, edges fingerprint %s", name, var.root, fp)
        vcfg = load_config(cfg.source, name)
        admitted = derived.admitted_predicate(cfg.get("filters"), vcfg.get("filters"))
        _check_depth(var("centrality_top.csv"), "rank", k_c, f"{name}/centrality_top.csv")
        _check_depth(var("bridges_top.csv"), "bridge_rank", k_b, f"{name}/bridges_top.csv")
        lists.append(
            derived.sensitivity_top_lists(
                name,
                main("centrality_top.csv"),
                var("centrality_top.csv"),
                main("bridges_top.csv"),
                var("bridges_top.csv"),
                k_c,
                k_b,
                admitted,
            )
        )
        agree.append(
            derived.sensitivity_agreement(
                name, main("centrality_agreement.csv"), var("centrality_agreement.csv")
            )
        )
    return pd.concat(lists, ignore_index=True), pd.concat(agree, ignore_index=True)


def run(cfg: Config) -> None:
    out_tables = results_dir(cfg, MAIN_GRAPH)
    out_figures = figures_dir(cfg, MAIN_GRAPH)
    main = Tables(out_tables)
    fingerprint = check_one_build(main, MAIN_GRAPH)
    log.info("main graph %s: %s, edges fingerprint %s", MAIN_GRAPH, out_tables, fingerprint)

    # Derived CSVs (report numbers must live in reports/tables, RULES §9).
    sens_lists, sens_agree = sensitivity(cfg, main)
    fates = derived.instance_fates(main("graph_build_summary.csv"), MAIN_GRAPH, fingerprint)
    funnel = derived.pipeline_funnel(
        main("profile_row_counts.csv"),
        main("profile_summary.csv"),
        main("graph_build_summary.csv"),
        main("gds_projections.csv"),
        MAIN_GRAPH,
        fingerprint,
    )
    for name, frame in (
        ("sensitivity_top_lists.csv", sens_lists),
        ("sensitivity_agreement.csv", sens_agree),
        ("graph_instances.csv", fates),
        ("pipeline_funnel.csv", funnel),
    ):
        log.info("%s: %d rows -> %s", name, len(frame), write_table(frame, out_tables / name))
    for r in sens_lists.itertuples():
        log.info(
            "  %-10s %-17s %-14s top-%d Jaccard %.3f, %d entrants, admitted: %s",
            r.variant,
            r.projection,
            r.measure,
            r.k,
            r.jaccard,
            r.entrants,
            r.admitted_names or "-",
        )

    # Figures.
    drawn = [
        figures.benchmark_pagerank(
            main("benchmark_pagerank_summary.csv"),
            main("benchmark_pagerank_agreement.csv"),
            out_figures / "benchmark_pagerank.png",
        ),
        figures.centrality_agreement(
            main("centrality_agreement.csv"), out_figures / "centrality_agreement.png"
        ),
        figures.communities_sizes(
            main("communities_sizes.csv"),
            main("communities_runs.csv"),
            out_figures / "communities_sizes.png",
        ),
        figures.communities_composition(
            main("communities_top.csv"), out_figures / "communities_composition.png"
        ),
        figures.validation_ranks(
            main("validation_ranks.csv"),
            main("validation_summary.csv"),
            out_figures / "validation_ranks.png",
        ),
        figures.trends_edge_types(
            main("trends_by_decade.csv"), out_figures / "trends_edge_types.png"
        ),
        figures.graph_build_instances(fates, funnel, out_figures / "graph_build_instances.png"),
    ]
    for path in drawn:
        log.info("figure -> %s", path)

    # Report-ready tables; the folder is rewritten as a whole (NFR-03).
    report: list[ReportTable] = [
        tables.data_funnel(funnel),
        tables.data_genres(main("genre_parent_summary.csv")),
        tables.graph_instances(fates),
        tables.data_quality(main("graph_checks.csv")),
        tables.bridges_top(main("bridges_top.csv")),
        tables.bridges_summary(main("bridges_summary.csv")),
        tables.validation(main("validation_ranks.csv"), main("validation_summary.csv")),
        tables.communities_runs(main("communities_runs.csv"), main("communities_stability.csv")),
        tables.communities_top(main("communities_top.csv")),
        tables.trends(main("trends_by_decade.csv")),
        *[
            tables.centrality_top(main("centrality_top.csv"), p)
            for p in sorted(main("centrality_top.csv")["projection"].unique())
        ],
        tables.centrality_agreement(main("centrality_agreement.csv")),
        tables.centrality_runs(main("centrality_runs.csv")),
        tables.separation(main("separation_paths.csv")),
        tables.sensitivity_lists(sens_lists),
        tables.sensitivity_agreement(sens_agree),
        tables.bench_scaling(main("benchmark_scaling_summary.csv")),
        tables.bench_pagerank(
            main("benchmark_pagerank_summary.csv"), main("benchmark_pagerank_agreement.csv")
        ),
        tables.bench_environment(
            main("benchmark_environment.csv"), main("benchmark_pagerank_runs.csv")
        ),
    ]
    report_dir = out_tables / "report"
    if report_dir.exists():
        shutil.rmtree(report_dir)
    for t in report:
        write_table_files(t, report_dir)
    log.info("%d report tables (.md + .tex) -> %s", len(report), report_dir)

    # Manifest of every figure and table under reports/.
    reports_root = out_tables.parent
    text, unlisted = render(reports_root, report)
    manifest = reports_root / "README.md"
    manifest.write_text(text, encoding="utf-8", newline="\n")
    for rel in unlisted:
        log.warning("not catalogued in the manifest: reports/%s", rel)
    log.info("manifest -> %s (%d uncatalogued files)", manifest, len(unlisted))


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--config", required=True, help="path to config/pipeline.yaml")
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    start = time.monotonic()
    try:
        run(load_config(args.config))
    finally:
        log.info("done in %.1fs", time.monotonic() - start)
    return 0


if __name__ == "__main__":
    sys.exit(main())
